CREATE OR REPLACE FUNCTION private.org_commands_v2(changes_ jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb; result_ jsonb:='[]'; n integer; BEGIN FOR x IN SELECT value FROM jsonb_array_elements(changes_) LOOP IF x->>'action'='roles' THEN SELECT count(*) INTO n FROM jsonb_array_elements(x->'data'->'roles') r WHERE coalesce((r->>'is_primary')::boolean,false); IF jsonb_typeof(x->'data'->'roles') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'data'->'roles')>20 OR (jsonb_array_length(x->'data'->'roles')>0 AND n<>1) OR EXISTS(SELECT 1 FROM jsonb_array_elements(x->'data'->'roles') r GROUP BY r->>'role_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Chọn đúng một Role chính, không trùng Role.';END IF; END IF;result_:=result_||private.org_commands(jsonb_build_array(x)); END LOOP; RETURN result_; END $$;
CREATE OR REPLACE FUNCTION private.org_effect_signature(c jsonb,changes_ jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT jsonb_build_object('units',c->'units','titles',c->'titles','assignments',(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM (SELECT jsonb_build_object('unit_id',m->>'unit_id','title_id',m->>'title_id','user_id',m->>'user_id','category',m->>'category','starts_at',m->>'starts_at','ends_at',m->>'ends_at','status',m->>'status') x FROM jsonb_array_elements(c->'memberships')m)s),'permissions',jsonb_build_object('defaults',c->'defaults','bundles',c->'bundles','grants',c->'grants','bindings',c->'bindings')) $$;
CREATE OR REPLACE FUNCTION public.org_change(_phase text,_revision bigint DEFAULT NULL,_change jsonb DEFAULT NULL,_preview uuid DEFAULT NULL,_confirmation text DEFAULT NULL,_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record;before_ jsonb;after_ jsonb;units_ jsonb;id_ uuid;rev_ bigint;fingerprint_ text;normalized_ jsonb;BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) THEN RAISE EXCEPTION 'Vui lòng đăng nhập lại.';END IF;IF _phase NOT IN ('preview','apply') THEN RAISE EXCEPTION 'Giai đoạn không hợp lệ.';END IF;PERFORM pg_advisory_xact_lock(hashtext('canonical_org')); PERFORM pg_advisory_xact_lock(hashtext('base_org')); PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));LOCK TABLE org_units,org_titles,org_assignments,base_org_state,biz_systems,biz_departments,biz_teams,biz_positions,biz_appointments,biz_department_members,biz_team_members,biz_member_affiliations,biz_management_assignments,biz_department_system_history,base_title_role_links IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE profiles,user_roles,app_roles,biz_approval_workflows,biz_access_exceptions IN SHARE MODE; SELECT revision INTO rev_ FROM private.org_control WHERE id FOR UPDATE;before_:=private.org_config();fingerprint_:=private.org_fingerprint();
 IF _phase='preview' THEN IF _revision IS DISTINCT FROM rev_ THEN RAISE EXCEPTION 'Nguồn cơ cấu đã thay đổi; xem trước lại.';END IF;IF jsonb_typeof(_change) IS DISTINCT FROM 'array' OR jsonb_array_length(_change) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Danh sách thay đổi không hợp lệ.';END IF;SELECT jsonb_agg(x||jsonb_build_object('data',coalesce(x->'data','{}')||jsonb_build_object('id',coalesce(nullif(x->'data'->>'id',''),gen_random_uuid()::text))||CASE WHEN x->>'action'='assign' AND nullif(x->'data'->>'starts_at','') IS NULL THEN jsonb_build_object('starts_at',clock_timestamp()) WHEN x->>'action'='end' AND nullif(x->'data'->>'ends_at','') IS NULL THEN jsonb_build_object('ends_at',clock_timestamp()) ELSE '{}'::jsonb END)) INTO normalized_ FROM jsonb_array_elements(_change)x;INSERT INTO private.org_previews(actor_id,revision,baseline,changes,impact,next_transition_at) VALUES(auth.uid(),rev_,fingerprint_,normalized_,'{}',(SELECT min(ts) FROM (SELECT starts_at ts FROM org_assignments UNION ALL SELECT ends_at FROM org_assignments)x WHERE ts>clock_timestamp())) RETURNING id INTO id_;
 BEGIN INSERT INTO private.org_execution(transaction_id,actor_id,preview_id) VALUES(txid_current(),auth.uid(),id_);units_:=private.org_commands_v2(normalized_);after_:=private.org_config();RAISE EXCEPTION USING ERRCODE='ZX001',MESSAGE='rollback preview';EXCEPTION WHEN SQLSTATE 'ZX001' THEN NULL;END;UPDATE private.org_previews SET impact=jsonb_build_object('before',before_,'after',after_,'signature',private.org_effect_signature(after_,normalized_),'units',units_) WHERE id=id_;RETURN jsonb_build_object('id',id_,'revision',rev_,'impact','[]'::jsonb,'before',before_,'after',after_,'units',units_,'expires_at',clock_timestamp()+interval '10 minutes');END IF;
 SELECT * INTO p FROM private.org_previews WHERE id=_preview AND actor_id=auth.uid() FOR UPDATE;IF NOT FOUND OR p.applied_at IS NOT NULL OR p.expires_at<=clock_timestamp() OR p.next_transition_at<=clock_timestamp() THEN RAISE EXCEPTION 'Xem trước hết hạn/đã dùng hoặc hiệu lực đã thay đổi.';END IF;IF p.revision<>rev_ OR p.baseline<>fingerprint_ THEN RAISE EXCEPTION 'Nguồn cơ cấu/quyền đã thay đổi; xem trước lại.';END IF;IF coalesce(trim(_reason),'')='' OR _confirmation IS DISTINCT FROM 'ÁP DỤNG CƠ CẤU' THEN RAISE EXCEPTION 'Cần lý do và xác nhận ÁP DỤNG CƠ CẤU.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(p.changes) x WHERE x->>'action' IN ('roles','permissions')) AND _reason NOT LIKE 'ÁP DỤNG PHÂN QUYỀN:%' THEN RAISE EXCEPTION 'Thay đổi quyền cần xác nhận ÁP DỤNG PHÂN QUYỀN: và lý do.';END IF;
 INSERT INTO private.org_execution(transaction_id,actor_id,preview_id) VALUES(txid_current(),auth.uid(),p.id);units_:=private.org_commands_v2(p.changes);after_:=private.org_config();IF private.org_effect_signature(after_,p.changes) IS DISTINCT FROM p.impact->'signature' THEN RAISE EXCEPTION 'Tác động đã thay đổi; cần xem trước lại.';END IF;INSERT INTO base_org_state(id,revision,config) VALUES(true,rev_+1,after_) ON CONFLICT(id) DO UPDATE SET revision=rev_+1,config=after_,updated_at=now();UPDATE private.org_control SET revision=rev_+1 WHERE id;INSERT INTO org_events(actor_id,before_revision,after_revision,unit_ids,reason,before_data,after_data) VALUES(auth.uid(),rev_,rev_+1,units_,trim(_reason),before_,after_);UPDATE private.org_previews SET applied_at=clock_timestamp() WHERE id=p.id;DELETE FROM private.org_execution WHERE transaction_id=txid_current();RETURN jsonb_build_object('revision',rev_+1);END $$;
REVOKE ALL ON FUNCTION private.org_commands_v2(jsonb) FROM PUBLIC,anon,authenticated,service_role;